```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
    terminal: false
});

let lines = [];
rl.on('line', (line) => {
    lines.push(line);
});

rl.on('close', () => {
    // 入力の解析
    const total = parseInt(lines[0] || '100', 10);
    const iteration = parseInt(lines[1] || '0', 10);
    const prefix = lines[2] || '';
    const suffix = lines[3] || '';
    const length = parseInt(lines[4] || '30', 10);
    const fill = lines[5] || '█';
    const printEnd = lines[6] || '\r';

    // プログレスバー生成関数
    function progressBar(iteration, total, prefix = '', suffix = '', decimals = 0, length = 30, fill = '█', printEnd = '\r') {
        const percent = (iteration / total).toFixed(decimals);
        const filledLength = Math.floor(length * iteration / total);
        const bar = fill.repeat(filledLength) + '-'.repeat(length - filledLength);
        return `${prefix} |${bar}| ${percent}% ${suffix}${printEnd}`;
    }

    // 出力（decimalsは仕様上指定がないため0と仮定）
    const result = progressBar(iteration, total, prefix, suffix, 0, length, fill, printEnd);
    process.stdout.write(result);
});
```

