function _get_alloc_cmd(nodes, time = null, account = null, options = null) {
    const salloc_args = ['--no-shell', '-N', String(nodes), '-J', 'SmartSim'];
    if (time) {
        salloc_args.push('-t', _validate_time_format(time));
    }
    if (account) {
        salloc_args.push('-A', String(account));
    }
    const argumentsSet = new Set(options ? Object.keys(options) : []);
    const invalid = new Set(['t', 'time', 'N', 'nodes', 'A', 'account']);
    const valid = new Set([...argumentsSet].filter(x => invalid.has(x)));
    if (valid.size > 0) {
        throw new Error(`Expecting time, nodes, account as an argument. Also received: ${[...valid]}`);
