    if (options) {
        for (const [opt, val] of Object.entries(options)) {
            const short_arg = String(opt).length === 2;
            const prefix = short_arg ? '-' : '--';
            if (!val) {
                salloc_args.push(prefix + opt);
            } else if (short_arg) {
                salloc_args.push(prefix + opt, String(val));
            } else {
                salloc_args.push(prefix + opt + '=' + String(val));
            }
        }
    }
