```typescript
import * as readline from 'readline';

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false
});

const entityMappings: { [key: string]: { B: string; I: string } } = {
  'nam_liv': { B: 'B-PER', I: 'I-PER' },
  'nam_loc': { B: 'B-LOC', I: 'I-LOC' },
  'nam_org': { B: 'B-ORG', I: 'I-ORG' }
};

function mapSingleLabel(labelName: string): string {
  if (labelName === 'O') return 'O';

  const prefix = labelName.slice(0, 2);
  const entityPart = labelName.slice(2);

  if (prefix === 'B-' || prefix === 'I-') {
    const mapping = entityMappings[entityPart];
    if (mapping) {
      return prefix === 'B-' ? mapping.B : mapping.I;
    }
    return prefix === 'B-' ? 'B-MISC' : 'I-MISC';
  }

  return 'O';
}

rl.on('line', (line) => {
  const trimmed = line.trim();
  if (trimmed) {
    console.log(mapSingleLabel(trimmed));
  }
});
