実装方針：正規表現を用いて、文字列中の最初のIPA発音記号（/.../ または [...] で囲まれた部分）を抽出します。

```java
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLine()) {
            String line = sc.nextLine();
            String result = extractFirstIPA(line);
            System.out.println(result);
        }
        sc.close();
    }

    private static String extractFirstIPA(String input) {
        // IPA発音記号は通常 /.../ または [...] で囲まれる
        Pattern pattern = Pattern.compile("[/\\[][^/\\[\\]]+[/\\]]");
        Matcher matcher = pattern.matcher(input);
        if (matcher.find()) {
            return matcher.group();
        }
        // 見つからない場合は入力そのまま返す（仕様に従い）
        return input;
    }
}
```

実装方針: 元のPythonコードの処理をJavaで再現し、配列の平均化ダウンサンプリングを効率的に行うために、入力データをパースしてから指定された軸方向に平均化処理を実施します。

```java
import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        List<String> lines = new ArrayList<>();
        while ((line = br.readLine()) != null && !line.isEmpty()) {
            lines.add(line.trim());
        }
        if (lines.size() < 4) return;

        // 入力パース
        String dataStr = lines.get(0);
        int n = Integer.parseInt(lines.get(1));
        int axis = Integer.parseInt(lines.get(2));
        String xvals = lines.get(3);

        // データ配列をパース
        double[] data = parseArray(dataStr);

        // ダウンサンプリング実行
        double[] result = downsample(data, n, axis);

        // 出力
        System.out.println(Arrays.toString(result).replace(" ", ""));
    }

    private static double[] parseArray(String s) {
        s = s.replace("[", "").replace("]", "");
        String[] parts = s.split(",");
        double[] arr = new double[parts.length];
        for (int i = 0; i < parts.length; i++) {
            arr[i] = Double.parseDouble(parts[i].trim());
        }
        return arr;
    }

    private static double[] downsample(double[] data, int n, int axis) {
        if (n <= 1 || axis != 0) return data; // 1次元のみ対応
        int nPts = data.length / n;
        if (nPts == 0) return data;

        double[] result = new double[nPts];
        for (int i = 0; i < nPts; i++) {
            double sum = 0;
            for (int j = 0; j < n; j++) {
                sum += data[i * n + j];
            }
            result[i] = sum / n;
        }
        return result;
    }
}
```

実装方針: 入力された値がタプル形式かどうかを判定し、タプルなら2番目の要素をモデルとして、2番目の要素のタプルから開始・終了インデックスを取得し、タプルでなければその値をモデルとして開始・終了を(1, -1)に設定する。

```java
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String input = sc.nextLine().trim();

        // 入力がタプル形式かどうかを判定
        if (input.startsWith("(") && input.endsWith(")")) {
            // タプル形式の場合
            String inner = input.substring(1, input.length() - 1);
            String[] parts = inner.split(",", 2);
            String modelPart = parts[0].trim();
            String indicesPart = parts[1].trim();

            // インデックス部分を解析
            String indicesInner = indicesPart.substring(1, indicesPart.length() - 1);
            String[] indices = indicesInner.split(",");
            int bgn = Integer.parseInt(indices[0].trim());
            int end = Integer.parseInt(indices[1].trim());

            // モデル部分を数値として解釈（簡易的に）
            int model = Integer.parseInt(modelPart);

            System.out.println("[" + model + ", " + bgn + ", " + end + "]");
        } else {
            // タプルでない場合
            int model = Integer.parseInt(input);
            System.out.println("[" + model + ", 1, -1]");
        }
    }
}
