```cpp
#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <algorithm>

// ボリュームを表す3次元配列
using Volume = std::vector<std::vector<std::vector<int>>>;

// 文字列をパースしてボリュームリストを取得
std::vector<Volume> parseVolumes(const std::string& input) {
    std::vector<Volume> volumes;
    std::string s = input;
    // 外側の[]を除去
    s = s.substr(1, s.size() - 2);
    std::stringstream ss(s);
    std::string token;
    while (std::getline(ss, token, ']')) {
        // 各ボリュームの開始位置を探す
        size_t start = token.find('[');
        if (start == std::string::npos) continue;
        std::string volStr = token.substr(start + 1);
        // カンマ区切りで数値を取得
        std::stringstream vss(volStr);
        std::string num;
        Volume vol;
        std::vector<std::vector<int>> slice;
        std::vector<int> row;
        while (std::getline(vss, num, ',')) {
            // 空白除去
            num.erase(std::remove_if(num.begin(), num.end(), ::isspace), num.end());
            if (num.empty()) continue;
            if (num == "[") {
                // 新しいスライス開始
                if (!row.empty()) {
                    slice.push_back(row);
                    row.clear();
                }
                if (!slice.empty()) {
                    vol.push_back(slice);
                    slice.clear();
                }
                continue;
            }
            if (num == "]") {
                if (!row.empty()) {
                    slice.push_back(row);
                    row.clear();
                }
                if (!slice.empty()) {
                    vol.push_back(slice);
                    slice.clear();
                }
                continue;
            }
            // 数値の場合
            row.push_back(std::stoi(num));
        }
        // 最後の処理
        if (!row.empty()) slice.push_back(row);
        if (!slice.empty()) vol.push_back(slice);
        if (!vol.empty()) volumes.push_back(vol);
    }
    return volumes;
}

// ボリュームを出力
void printVolume(const Volume& vol) {
    std::cout << "[";
    for (size_t i = 0; i < vol.size(); ++i) {
        std::cout << "[";
        for (size_t j = 0; j < vol[i].size(); ++j) {
            std::cout << "[";
            for (size_t k = 0; k < vol[i][j].size(); ++k) {
                std::cout << vol[i][j][k];
                if (k + 1 < vol[i][j].size()) std::cout << ", ";
            }
            std::cout << "]";
            if (j + 1 < vol[i].size()) std::cout << ", ";
        }
        std::cout << "]";
        if (i + 1 < vol.size()) std::cout << ", ";
    }
    std::cout << "]";
}

// 軸の転置
Volume transposeVolume(const Volume& vol, const std::string& direction) {
    if (direction == "axial") {
        // 軸順: (z, y, x) -> (z, x, y) つまり yとxを入れ替え
        Volume result;
        for (size_t z = 0; z < vol.size(); ++z) {
            std::vector<std::vector<int>> slice;
            size_t y_size = vol[z].size();
            size_t x_size = vol[z][0].size();
            for (size_t x = 0; x < x_size; ++x) {
                std::vector<int> row;
                for (size_t y = 0; y < y_size; ++y) {
                    row.push_back(vol[z][y][x]);
                }
                slice.push_back(row);
            }
            result.push_back(slice);
        }
        return result;
    } else if (direction == "sagittal") {
        // 軸順: (z, y, x) -> (x, y, z) つまりzとxを入れ替え
        Volume result;
        size_t z_size = vol.size();
        size_t y_size = vol[0].size();
        size_t x_size = vol[0][0].size();
        for (size_t x = 0; x < x_size; ++x) {
            std::vector<std::vector<int>> slice;
            for (size_t y = 0; y < y_size; ++y) {
                std::vector<int> row;
                for (size_t z = 0; z < z_size; ++z) {
                    row.push_back(vol[z][y][x]);
                }
                slice.push_back(row);
            }
            result.push_back(slice);
        }
        return result;
    } else if (direction == "coronal") {
        // 軸順: (z, y, x) -> (y, z, x) つまりzとyを入れ替え
        Volume result;
        size_t z_size = vol.size();
        size_t y_size = vol[0].size();
        size_t x_size = vol[0][0].size();
        for (size_t y = 0; y < y_size; ++y) {
            std::vector<std::vector<int>> slice;
            for (size_t z = 0; z < z_size; ++z) {
                std::vector<int> row;
                for (size_t x = 0; x < x_size; ++x) {
                    row.push_back(vol[z][y][x]);
                }
                slice.push_back(row);
            }
            result.push_back(slice);
        }
        return result;
    }
    return vol;
}

int main() {
    std::string input_line, direction_line;
    std::getline(std::cin, input_line);
    std::getline(std::cin, direction_line);

    // 方向の空白除去
    direction_line.erase(std::remove_if(direction_line.begin(), direction_line.end(), ::isspace), direction_line.end());

    std::vector<Volume> volumes = parseVolumes(input_line);
    std::vector<Volume> tr_volumes;
    for (const auto& vol : volumes) {
        tr_volumes.push_back(transposeVolume(vol, direction_line));
    }

    // 出力
    std::cout << "[";
    for (size_t i = 0; i < tr_volumes.size(); ++i) {
        printVolume(tr_volumes[i]);
        if (i + 1 < tr_volumes.size()) std::cout << ", ";
    }
    std::cout << "]" << std::endl;

    return 0;
}
