実装方針: 入力値を文字列として読み取り、Pythonの型判定を模倣するために、数値・真偽値・null・配列・辞書などのJSON風表現を再帰的に解析して、BiDi形式へ変換します。

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <cmath>
#include <sstream>
#include <algorithm>
#include <cctype>

// 簡易JSONパーサーとシリアライザー
class JsonValue {
public:
    enum Type { Null, Bool, Number, BigInt, String, Array, Object, Set, SharedRef };
    Type type;
    bool boolVal;
    double numVal;
    std::string strVal;
    std::vector<JsonValue> arrayVal;
    std::vector<std::pair<std::string, JsonValue>> objectVal;
    std::string sharedId;

    JsonValue() : type(Null) {}
};

// パーサー: 文字列をJsonValueに変換
class Parser {
    std::string s;
    size_t pos = 0;
public:
    Parser(const std::string& str) : s(str) {}

    JsonValue parse() {
        skipWhitespace();
        return parseValue();
    }

private:
    void skipWhitespace() {
        while (pos < s.size() && isspace(s[pos])) pos++;
    }

    JsonValue parseValue() {
        if (pos >= s.size()) return JsonValue();
        char c = s[pos];
        if (c == 'n') return parseNull();
        if (c == 't' || c == 'f') return parseBool();
        if (c == '"') return parseString();
        if (c == '[') return parseArray();
        if (c == '{') return parseObject();
        if (c == '-' || isdigit(c)) return parseNumber();
        return JsonValue();
    }

    JsonValue parseNull() {
        if (s.substr(pos, 4) == "null") { pos += 4; return JsonValue(); }
        return JsonValue();
    }

    JsonValue parseBool() {
        if (s.substr(pos, 4) == "true") { pos += 4; JsonValue v; v.type = JsonValue::Bool; v.boolVal = true; return v; }
        if (s.substr(pos, 5) == "false") { pos += 5; JsonValue v; v.type = JsonValue::Bool; v.boolVal = false; return v; }
        return JsonValue();
    }

    JsonValue parseString() {
        pos++; // skip "
        std::string result;
        while (pos < s.size() && s[pos] != '"') {
            if (s[pos] == '\\' && pos+1 < s.size()) {
                char next = s[pos+1];
                if (next == 'n') result += '\n';
                else if (next == 't') result += '\t';
                else if (next == 'r') result += '\r';
                else if (next == '\\') result += '\\';
                else if (next == '"') result += '"';
                else if (next == 'u') {
                    // 簡易unicode (省略)
                    result += "?";
                    pos += 4;
                } else result += next;
                pos += 2;
            } else {
                result += s[pos];
                pos++;
            }
        }
        pos++; // skip "
        JsonValue v;
        v.type = JsonValue::String;
        v.strVal = result;
        return v;
    }

    JsonValue parseNumber() {
        size_t start = pos;
        if (s[pos] == '-') pos++;
        while (pos < s.size() && (isdigit(s[pos]) || s[pos] == '.' || s[pos] == 'e' || s[pos] == 'E' || s[pos] == '+' || s[pos] == '-')) pos++;
        std::string numStr = s.substr(start, pos-start);
        // 整数か浮動小数か判定
        bool isFloat = numStr.find('.') != std::string::npos || numStr.find('e') != std::string::npos || numStr.find('E') != std::string::npos;
        JsonValue v;
        if (isFloat) {
            v.type = JsonValue::Number;
            v.numVal = std::stod(numStr);
        } else {
            // 整数
            long long ll = std::stoll(numStr);
            if (ll > 9007199254740991LL || ll < -9007199254740991LL) {
                v.type = JsonValue::BigInt;
                v.strVal = numStr;
            } else {
                v.type = JsonValue::Number;
                v.numVal = (double)ll;
            }
        }
        return v;
    }

    JsonValue parseArray() {
        pos++; // skip [
        JsonValue v;
        v.type = JsonValue::Array;
        skipWhitespace();
        if (pos < s.size() && s[pos] == ']') { pos++; return v; }
        while (pos < s.size()) {
            v.arrayVal.push_back(parseValue());
            skipWhitespace();
            if (pos < s.size() && s[pos] == ',') { pos++; skipWhitespace(); }
            else if (pos < s.size() && s[pos] == ']') { pos++; break; }
        }
        return v;
    }

    JsonValue parseObject() {
        pos++; // skip {
        JsonValue v;
        v.type = JsonValue::Object;
        skipWhitespace();
        if (pos < s.size() && s[pos] == '}') { pos++; return v; }
        while (pos < s.size()) {
            JsonValue key = parseValue();
            skipWhitespace();
            if (pos < s.size() && s[pos] == ':') { pos++; skipWhitespace(); }
            JsonValue val = parseValue();
            v.objectVal.push_back({key.strVal, val});
            skipWhitespace();
            if (pos < s.size() && s[pos] == ',') { pos++; skipWhitespace(); }
            else if (pos < s.size() && s[pos] == '}') { pos++; break; }
        }
        return v;
    }
};

// シリアライザー: JsonValueをBiDi形式に変換
std::string serializeValue(const JsonValue& v) {
    switch (v.type) {
        case JsonValue::Null:
            return "{\"type\":\"null\"}";
        case JsonValue::Bool:
            return "{\"type\":\"boolean\",\"value\":" + std::string(v.boolVal ? "true" : "false") + "}";
        case JsonValue::Number: {
            double d = v.numVal;
            if (std::isnan(d)) return "{\"type\":\"number\",\"value\":\"NaN\"}";
            if (std::isinf(d)) return "{\"type\":\"number\",\"value\":\"" + std::string(d > 0 ? "Infinity" : "-Infinity") + "\"}";
            if (d == 0.0 && std::signbit(d)) return "{\"type\":\"number\",\"value\":\"-0\"}";
            std::ostringstream oss;
            oss << d;
            return "{\"type\":\"number\",\"value\":" + oss.str() + "}";
        }
        case JsonValue::BigInt:
            return "{\"type\":\"bigint\",\"value\":\"" + v.strVal + "\"}";
        case JsonValue::String:
            return "{\"type\":\"string\",\"value\":\"" + v.strVal + "\"}";
        case JsonValue::Array: {
            std::string result = "{\"type\":\"array\",\"value\":[";
            for (size_t i = 0; i < v.arrayVal.size(); i++) {
                if (i > 0) result += ",";
                result += serializeValue(v.arrayVal[i]);
            }
            result += "]}";
            return result;
        }
        case JsonValue::Object: {
            // sharedIdチェック
            for (const auto& p : v.objectVal) {
                if (p.first == "sharedId") {
                    return "{\"type\":\"sharedReference\",\"sharedId\":\"" + p.second.strVal + "\"}";
                }
            }
            std::string result = "{\"type\":\"object\",\"value\":[";
            for (size_t i = 0; i < v.objectVal.size(); i++) {
                if (i > 0) result += ",";
                result += "[\"" + v.objectVal[i].first + "\"," + serializeValue(v.objectVal[i].second) + "]";
            }
            result += "]}";
            return result;
        }
        default:
            return "{\"type\":\"string\",\"value\":\"\"}";
    }
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        Parser parser(line);
        JsonValue val = parser.parse();
        std::cout << serializeValue(val) << std::endl;
    }
    return 0;
}
