```csharp
using System;
using System.Collections.Generic;

class Program
{
    static List<object> AsList(params object[] whatever)
    {
        var result = new List<object>();
        foreach (var w in whatever)
        {
            if (w == null)
                continue;
            if (w is System.Collections.IEnumerable && !(w is string))
            {
                foreach (var item in (System.Collections.IEnumerable)w)
                {
                    result.Add(item);
                }
            }
            else
            {
                result.Add(w);
            }
        }
        return result;
    }

    static void Main()
    {
        string input;
        var args = new List<object>();
        while ((input = Console.ReadLine()) != null && input.Length > 0)
        {
            args.Add(input);
        }
        var result = AsList(args.ToArray());
        Console.WriteLine("[" + string.Join(", ", result.ConvertAll(x => "\"" + x + "\"")) + "]");
    }
}
