                else if (item is Dictionary<string, object> dict)
                {
                    string blockType = dict.ContainsKey("type") ? dict["type"] as string : null;
                    if (blockType == "text")
                        part = dict.ContainsKey("text") ? dict["text"] as string : "";
                    else if (blockType == "tool_use")
                        part = _format_tool_use(dict);
                    else if (blockType == "tool_result")
                    {
                        string tid = dict.ContainsKey("tool_use_id") ? dict["tool_use_id"] as string : "";
                        string tname = (tool_use_map != null && tool_use_map.ContainsKey(tid)) ? tool_use_map[tid] : "Unknown";
                        object resultContent = dict.ContainsKey("content") ? dict["content"] : "";
                        string formatted = _format_tool_result(resultContent, tname);
                        if (!string.IsNullOrEmpty(formatted))
                            part = formatted;
                    }
                }
                if (!string.IsNullOrEmpty(part))
                {
                    if (sb.Length > 0) sb.Append('\n');
                    sb.Append(part);
                }
            }
            return sb.ToString().Trim();
