```csharp
using System;

class Program
{
    static bool IsTorchOOM(Exception exc)
    {
        if (exc == null) return false;

        string typeName = exc.GetType().FullName ?? "";
        if (typeName.Contains("torch.cuda.OutOfMemoryError"))
            return true;

        string message = exc.Message ?? "";
        if (message.Contains("CUDA out of memory") ||
