```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func isRetryable(module, name string) bool {
	// 組み込み例外のチェック
	if name == "TimeoutError" || name == "ConnectionError" {
		return true
	}
	// httpx以外のモジュールで特定の例外名
	if module != "httpx" && (name == "ConnectError" || name == "ReadError" || name == "WriteError" || name == "TimeoutException" || name == "NetworkError") {
		return true
	}
	// openaiモジュールの特定の例外
	return module == "openai" && (name == "RateLimitError" || name == "InternalServerError" || name == "APITimeoutError" || name == "APIConnectionError")
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		input := strings.TrimSpace(scanner.Text())
		if input == "" {
