		parts := strings.Split(input, ".")
		var module, name string
		if len(parts) == 1 {
			module = ""
			name = parts[0]
		} else {
			module = strings.Join(parts[:len(parts)-1], ".")
			name = parts[len(parts)-1]
		}
		result := isRetryable(module, name)
		fmt.Println(result)
	}
}
