実装方針: 標準入力から2行読み取り、1行目が小数値なら度分秒形式に変換し、2行目が1.0なら小数値、0.0なら度分秒形式で出力する。

```go
package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
)

func decimalToDMS(dec float64) string {
	deg := int(dec)
	minFloat := (dec - float64(deg)) * 60
	min := int(minFloat)
	sec := (minFloat - float64(min)) * 60
	return fmt.Sprintf("%d:%d:%.4f", deg, min, sec)
}

func dmsToDecimal(dms string) float64 {
	parts := strings.Split(dms, ":")
	if len(parts) != 3 {
		return 0
	}
	deg, _ := strconv.ParseFloat(parts[0], 64)
	min, _ := strconv.ParseFloat(parts[1], 64)
	sec, _ := strconv.ParseFloat(parts[2], 64)
	return deg + min/60 + sec/3600
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	lines := []string{}
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
		if len(lines) == 2 {
			break
		}
	}
	if len(lines) < 2 {
		return
	}

	input := strings.TrimSpace(lines[0])
	backStr := strings.TrimSpace(lines[1])
	back, _ := strconv.ParseFloat(backStr, 64)

	// 入力が小数形式か度分秒形式か判定
	if strings.Contains(input, ":") {
		// 度分秒 → 小数
		dec := dmsToDecimal(input)
		if back == 1.0 {
			fmt.Printf("%.4f\n", dec)
		} else {
			// 小数に変換してから度分秒に戻す（元の形式を維持）
			fmt.Println(input)
		}
	} else {
		// 小数 → 度分秒
		dec, _ := strconv.ParseFloat(input, 64)
		dms := decimalToDMS(dec)
		if back == 1.0 {
			fmt.Printf("%.4f\n", dec)
		} else {
			fmt.Println(dms)
		}
	}
}
```

実装方針: 標準入力から整数を読み取り、指定されたビット数（省略時は必要最小限）でLSBファーストのビットリストを生成して出力します。

```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func intToBits(n int, width ...int) []int {
	if n == 0 && len(width) == 0 {
		return []int{0}
	}
	bits := []int{}
	temp := n
	for temp > 0 {
		bits = append(bits, temp%2)
		temp /= 2
	}
	if len(width) > 0 {
		w := width[0]
		for len(bits) < w {
			bits = append(bits, 0)
		}
	}
	return bits
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	line1 := strings.TrimSpace(scanner.Text())
	n, _ := strconv.Atoi(line1)

	var result []int
	if scanner.Scan() {
		line2 := strings.TrimSpace(scanner.Text())
		if line2 != "" {
			w, _ := strconv.Atoi(line2)
			result = intToBits(n, w)
		} else {
			result = intToBits(n)
		}
	} else {
		result = intToBits(n)
	}

	fmt.Println(result)
}
```

