package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func calculateRangeParameter(partSize, partIndex, numParts int, totalSize *int) string {
	startRange := partIndex * partSize
	var endRange string
	if partIndex == numParts-1 {
		endRange = ""
		if totalSize != nil {
			endRange = strconv.Itoa(*totalSize - 1)
		}
	} else {
		endRange = strconv.Itoa(startRange + partSize - 1)
	}
	return fmt.Sprintf("bytes=%d-%s", startRange, endRange)
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	partSize, _ := strconv.Atoi(strings.TrimSpace(scanner.Text()))
	scanner.Scan()
	partIndex, _ := strconv.Atoi(strings.TrimSpace(scanner.Text()))
	scanner.Scan()
	numParts, _ := strconv.Atoi(strings.TrimSpace(scanner.Text()))
	scanner.Scan()
	totalSizeStr := strings.TrimSpace(scanner.Text())
	var totalSize *int
	if totalSizeStr != "" {
		ts, _ := strconv.Atoi(totalSizeStr)
		totalSize = &ts
	}

	result := calculateRangeParameter(partSize, partIndex, numParts, totalSize)
	fmt.Println(result)
}
