    let mut input = String::new();
    io::stdin().read_line(&mut input).expect("Failed to read line");
    let path = input.trim().to_string();

    let file = File::open(&path).expect("Failed to open file");
    let reader = BufReader::new(file);

    let mut positions: HashMap<String, Vec<(usize, usize)>> = HashMap::new();

    for (line_num, line) in reader.lines().enumerate() {
        if let Ok(line) = line {
            // tRNA遺伝子の位置情報を抽出（例: "tRNA-Gly 100-150" のような形式）
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 2 {
                let gene_name = parts[0].to_string();
                if gene_name.starts_with("tRNA") {
                    if let Some(pos_str) = parts.get(1) {
                        let pos_parts: Vec<&str> = pos_str.split('-').collect();
                        if pos_parts.len() == 2 {
                            if let (Ok(start), Ok(end)) = (pos_parts[0].parse::<usize>(), pos_parts[1].parse::<usize>()) {
                                positions.entry(gene_name).or_insert_with(Vec::new).push((start, end));
                            }
                        }
                    }
                }
            }
        }
    }

    // 結果を出力
    let mut result = String::new();
    result.push_str("{");
    let mut first = true;
    for (gene, pos_list) in &positions {
        if !first {
            result.push_str(", ");
        }
        first = false;
        result.push_str(&format!("\"{}\": [", gene));
        let mut pos_first = true;
        for (start, end) in pos_list {
            if !pos_first {
                result.push_str(", ");
            }
            pos_first = false;
            result.push_str(&format!("({}, {})", start, end));
        }
        result.push_str("]");
    }
    result.push_str("}");
    println!("{}", result);
}
