const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

const lines = [];
rl.on('line', line => lines.push(line));
rl.on('close', () => {
  const [iteration, total, prefix = '', suffix = '', decimals = 1, length = 100, fill = '█', printEnd = '\r'] = lines;

  const percent = (100 * (Number(iteration) / Number(total))).toFixed(Number(decimals));
  const filledLength = Math.floor(Number(length) * (Number(iteration) / Number(total)));
  const bar = fill.repeat(Math.min(filledLength, Number(length))) + '-'.repeat(Math.max(0, Number(length) - filledLength));

  process.stdout.write(`\r${prefix} |${bar}| ${percent}% ${suffix}${printEnd}`);
});
