標準入力から6つの引数を読み取り、Google Drive APIをHTTPSで直接呼び出す形で、元のPythonコードと同じ成功/失敗の結果を返すJavaScriptプログラムを実装します。

```javascript
const fs = require('fs');
const https = require('https');
const readline = require('readline');

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

class FileNotFoundError extends Error {}
class ValueError extends Error {}

function readJsonFile(path) {
  return JSON.parse(fs.readFileSync(path, 'utf8'));
}

function loadCredentials(credentialsPath) {
  let data;
  try {
    data = readJsonFile(credentialsPath);
  } catch (e) {
    if (e.code === 'ENOENT') throw new FileNotFoundError(`Credentials file not found: ${credentialsPath}`);
    throw new ValueError('Invalid credentials format');
  }

  const client = data.installed || data.web;
  if (!client || !client.client_id || !client.client_secret) {
    throw new ValueError('Invalid credentials format');
  }
  return client;
}

function loadToken(tokenPath, client) {
  let token;
  try {
    token = readJsonFile(tokenPath);
  } catch (e) {
    throw new FileNotFoundError(`Token file not found: ${tokenPath}`);
  }

  if (token.access_token) return token;

  if (token.refresh_token) {
    return refreshAccessToken(client, token.refresh_token, tokenPath);
  }

  throw new ValueError('Token file has no access_token or refresh_token');
}

function refreshAccessToken(client, refreshToken, tokenPath) {
  return new Promise((resolve, reject) => {
    const body = new URLSearchParams({
      client_id: client.client_id,
      client_secret: client.client_secret,
      refresh_token: refreshToken,
      grant_type: 'refresh_token',
    });

    const req = https.request({
      hostname: 'oauth2.googleapis.com',
      path: '/token',
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Content-Length': Buffer.byteLength(body.toString()),
      },
    }, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        if (res.statusCode !== 200) {
          reject(new HttpError(res.statusCode, 'Token refresh failed'));
          return;
        }
        try {
          const newToken = JSON.parse(data);
          newToken.refresh_token = refreshToken;
          fs.writeFileSync(tokenPath, JSON.stringify(newToken));
          resolve(newToken);
        } catch (e) {
          reject(new ValueError('Invalid token response'));
        }
      });
    });

    req.on('error', reject);
    req.write(body.toString());
    req.end();
  });
}

function httpsRequest(options, body = null) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve({ status: res.statusCode, data: data ? JSON.parse(data) : {} });
        } else {
          reject(new HttpError(res.statusCode, data));
        }
      });
    });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

function getDriveServiceOAuth(credentialsPath, tokenPath) {
  const client = loadCredentials(credentialsPath);
  const token = loadToken(tokenPath, client);
  return { client, token };
}

async function getFileMetadata(fileId, token) {
  const options = {
    hostname: 'www.googleapis.com',
    path: `/drive/v3/files/${encodeURIComponent(fileId)}?fields=name,size,mimeType&supportsAllDrives=true`,
    method: 'GET',
    headers: {
      Authorization: `Bearer ${token.access_token}`,
    },
  };

  const { data } = await httpsRequest(options);
  return data;
}

async function downloadFile(fileId, outputPath, token, verbose, maxRetries) {
  let attempt = 0;
  while (attempt < maxRetries) {
    try {
      const options = {
        hostname: 'www.googleapis.com',
        path: `/drive/v3/files/${encodeURIComponent(fileId)}?alt=media&supportsAllDrives=true`,
        method: 'GET',
        headers: {
          Authorization: `Bearer ${token.access_token}`,
        },
      };

      const res = await new Promise((resolve, reject) => {
        const req = https.request(options, (response) => {
          if (response.statusCode >= 200 && response.statusCode < 300) {
            resolve(response);
          } else {
            let errorData = '';
            response.on('data', (d) => errorData += d);
            response.on('end', () => reject(new HttpError(response.statusCode, errorData)));
          }
        });
        req.on('error', reject);
        req.end();
      });

      const total = parseInt(res.headers['content-length'] || '0', 10);
      const writeStream = fs.createWriteStream(outputPath, { flags: 'w' });
      let received = 0;

      await new Promise((resolve, reject) => {
        res.on('data', (chunk) => {
          received += chunk.length;
          if (verbose && total > 0) {
            const percent = Math.floor((received / total) * 100);
            const barLength = 40;
            const filled = Math.floor((received / total) * barLength);
            const bar = '█'.repeat(filled) + '░'.repeat(barLength - filled);
            process.stdout.write(`\rDownloading: |${bar}| ${percent}%`);
          }
        });
        writeStream.on('finish', resolve);
        writeStream.on('error', reject);
        res.on('error', reject);
        res.pipe(writeStream);
      });

      if (verbose) process.stdout.write('\n');
      return true;
    } catch (e) {
      if (e instanceof HttpError && [500, 502, 503, 504].includes(e.status)) {
        if (attempt < maxRetries - 1) {
          const wait = 2 ** attempt;
          if (verbose) process.stderr.write(`Server error (${e.status}), retrying in ${wait}s...\n`);
          await new Promise((resolve) => setTimeout(resolve, wait * 1000));
          attempt++;
          continue;
        }
      } else if (attempt < maxRetries - 1 && e.code && /connection|timeout|econnreset|econnrefused|etimedout|socket/i.test(e.code + e.message)) {
        const wait = 2 ** attempt;
        if (verbose) process.stderr.write(`Connection error, retrying in ${wait}s...\n`);
        await new Promise((resolve) => setTimeout(resolve, wait * 1000));
        attempt++;
        continue;
      }
      return false;
    }
  }
  return false;
}

async function downloadDriveFile(fileId, outputPath, credentialsPath, verbose, maxRetries, tokenPath) {
  try {
    const service = getDriveServiceOAuth(credentialsPath, tokenPath);
    const fileMetadata = await getFileMetadata(fileId, service.token);

    const fileName = fileMetadata.name || 'unknown';
    const fileSize = parseInt(fileMetadata.size || '0', 10);

    if (verbose) {
      console.error(`File found: ${fileName}`);
      console.error(`Size: ${(fileSize / (1024 ** 2)).toFixed(2)} MB`);
    }

    try {
      const outputDir = require('path').dirname(outputPath) || '.';
      const stat = fs.statfsSync(outputDir);
      const availableSpace = stat.bavail * stat.bsize;
      const requiredSpace = Math.floor(fileSize * 1.2);
      if (availableSpace < requiredSpace) {
        if (verbose) {
          console.error(`Error: Insufficient disk space`);
          console.error(`  Required: ${(requiredSpace / (1024 ** 3)).toFixed(2)} GB`);
          console.error(`  Available: ${(availableSpace / (1024 ** 3)).toFixed(2)} GB`);
        }
        return false;
      }
    } catch (e) {
      if (verbose) console.error(`Warning: Could not check disk space: ${e.message}`);
    }

    return await downloadFile(fileId, outputPath, service.token, verbose, maxRetries);
  } catch (e) {
    if (e instanceof FileNotFoundError || e instanceof ValueError || e instanceof HttpError) {
      if (verbose) console.error(`Authentication error: ${e.message}`);
      return false;
    }
    if (e instanceof HttpError) {
      if (e.status === 404) {
        if (verbose) {
          console.error(`Error: File not found on Google Drive (ID: ${fileId})`);
          console.error('Possible causes:');
          console.error('  - File ID is incorrect');
          console.error('  - File has been deleted');
          console.error('  - File is in trash');
        }
      } else if (e.status === 403) {
        if (verbose) {
          console.error(`Error: Permission denied to access file (ID: ${fileId})`);
          console.error('\nPossible causes:');
          console.error('  - File is not shared with you');
          console.error("  - You don't have permission to view this file");
          console.error('  - Try re-authenticating');
        }
      } else {
        if (verbose) console.error(`Error accessing file: ${e.message}`);
      }
      return false;
    }
    if (verbose) console.error(`Error getting file metadata: ${e.message}`);
    return false;
  }
}

const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
const lines = [];

rl.on('line', (line) => {
