const fs = require('fs');
const readline = require('readline');

function separateQTranslateTaggedLangs(text) {
  const qtStart = '[:';
  const qtEnd = ']';
  const qtEndLen = qtEnd.length;
  const qtEndWithLangLen = qtEndLen + 2; // [:LL] の LL と ] を取り除く長さ

  const qtChunks = text.split(qtStart);
  const contentByLang = {};
  const commonTxtList = [];

  for (let chunk of qtChunks) {
    if (!chunk.trim()) continue;

    let lang = '';
    if (chunk.startsWith(qtEnd)) {
      lang = '';
      chunk = chunk.replace(/^\]/, '');
      if (!chunk.trim()) continue;
    } else if (chunk.slice(2, qtEndWithLangLen).startsWith(qtEnd)) {
      lang = chunk.slice(0, 2);
      chunk = chunk.slice(qtEndWithLangLen);
    } else {
      lang = '';
    }

    if (!lang) {
      commonTxtList.push(chunk);
      for (const l of Object.keys(contentByLang)) {
        contentByLang[l].push(chunk);
      }
    } else {
      if (!contentByLang[lang]) {
        contentByLang[lang] = commonTxtList.slice();
      }
      contentByLang[lang].push(chunk);
    }
  }

  if (commonTxtList.length > 0 && Object.keys(contentByLang).length === 0) {
    contentByLang[''] = commonTxtList.slice();
  }

  for (const l of Object.keys(contentByLang)) {
    contentByLang[l] = contentByLang[l].join(' ');
  }

  return contentByLang;
}

const lines = [];
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false,
});

rl.on('line', (line) => {
  lines.push(line);
});

rl.on('close', () => {
  const text = lines.join('\n');
  const result = separateQTranslateTaggedLangs(text);
  process.stdout.write(JSON.stringify(result));
});
