import * as readline from 'readline';

function get(
  data: unknown,
  key: unknown,
  defaultValue: unknown = null,
  type?: (value: unknown) => unknown
): unknown {
  let found = true;
  let value: unknown;

  if (Array.isArray(data)) {
    const index = typeof key === "number" ? key : Number(key);
    if (Number.isInteger(index) && index >= 0 && index < data.length) {
      value = data[index];
    } else {
      found = false;
    }
  } else if (data !== null && typeof data === "object") {
    const object = data as Record<string, unknown>;
    const keyName = String(key);
    if (Object.prototype.hasOwnProperty.call(object, keyName)) {
      value = object[keyName];
    } else {
      found = false;
    }
  } else {
    found = false;
  }

  if (!found) {
    return defaultValue;
  }

  if (type !== undefined && type !== null) {
    try {
      return type(value);
    } catch {
      return defaultValue;
    }
  }

  return value;
}

function parseLine(line: string): unknown {
  const trimmed = line.trim();
  if (trimmed === "") {
    return undefined;
  }
  try {
    return JSON.parse(trimmed);
  } catch {
    return trimmed;
  }
}

function createTypeConverter(typeName: string): ((value: unknown) => unknown) | undefined {
  switch (typeName) {
    case "int":
    case "integer":
      return (value: unknown) => {
        const num = Number(value);
        if (value === "" || value === null || !Number.isFinite(num) || !Number.isInteger(num)) {
          throw new Error("ValueError");
        }
        return num;
      };
    case "float":
    case "number":
    case "Number":
      return (value: unknown) => {
        const num = Number(value);
        if (value === "" || value === null || !Number.isFinite(num)) {
          throw new Error("ValueError");
        }
        return num;
      };
    case "str":
    case "string":
    case "String":
      return (value: unknown) => String(value);
    default:
      return undefined;
  }
}

const lines: string[] = [];

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false,
});

rl.on("line", (line) => {
  lines.push(line);
});

rl.on("close", () => {
  const data = parseLine(lines[0] ?? "");
  const key = parseLine(lines[1] ?? "");
  const defaultValue = lines.length >= 3 ? parseLine(lines[2]) : null;
  const typeName = lines.length >= 4 ? lines[3].trim() : undefined;
  const type = typeName ? createTypeConverter(typeName) : undefined;

  const result = get(data, key, defaultValue, type);
  console.log(JSON.stringify(result));
});
