```typescript
import * as readline from 'readline';

const exactLabelMap: ReadonlyMap<string, string> = new Map([
  ['O', 'O'],
  ['B-nam_liv', 'B-PER'],
  ['I-nam_liv', 'I-PER'],
  ['B-nam_loc', 'B-LOC'],
  ['I-nam_loc', 'I-LOC'],
  ['B-nam_org', 'B-ORG'],
  ['I-nam_org', 'I-ORG'],
]);

const entityMappings: ReadonlyArray<readonly [string, readonly [string, string]]> = [
  ['nam_liv', ['B-PER', 'I-PER']],
  ['nam_loc', ['B-LOC', 'I-LOC']],
  ['nam_org', ['B-ORG', 'I-ORG']],
];

function mapSingleLabel(labelName: string): string {
  const exact = exactLabelMap.get(labelName);
  if (exact !== undefined) {
    return exact;
  }

  for (const [keyword, [bLabel, iLabel]] of entityMappings) {
    if (labelName.includes(keyword)) {
      if (labelName.startsWith('B-')) {
        return bLabel;
      }
      if (labelName.startsWith('I-')) {
        return iLabel;
      }
    }
  }

  if (labelName.startsWith('B-')) {
    return 'B-MISC';
  }
  if (labelName.startsWith('I-')) {
    return 'I-MISC';
  }
  return 'O';
}

async function main(): Promise<void> {
  const rl = readline.createInterface({
    input: process.stdin,
    crlfDelay: Infinity,
  });

  for await (const line of rl) {
    process.stdout.write(mapSingleLabel(line) + '\n');
  }
}

main();
