function safeReMatch(pattern: string | null, value: string): boolean {
    if (pattern === null) return true;
    try {
        return new RegExp(pattern).test(value);
    } catch {
        return false;
    }
}

function match(viewDict: any, selector: any): boolean {
    const requiredKeys = ['text', 'resource_id', 'class', 'bounds'];
    for (const key of requiredKeys) {
        if (!(key in viewDict)) return false;
    }

    if (selector.text_re !== null && !safeReMatch(selector.text_re, viewDict['text'])) return false;
    if (selector.resource_id_re !== null && !safeReMatch(selector.resource_id_re, viewDict['resource_id'])) return false;
    if (selector.content_desc_re !== null) {
        if (!('content_description' in viewDict)) return false;
        if (!safeReMatch(selector.content_desc_re, viewDict['content_description'])) return false;
    }
    if (selector.class_re !== null && !safeReMatch(selector.class_re, viewDict['class'])) return false;

    const bounds = viewDict['bounds'];
    const boundXMin = bounds[0][0];
    const boundXMax = bounds[1][0];
    const boundYMin = bounds[0][1];
    const boundYMax = bounds[1][1];

    for (const [x, y] of selector.in_coordinates) {
        if (x < boundXMin || x > boundXMax || y < boundYMin || y > boundYMax) {
            return false;
        }
    }

    for (const [x, y] of selector.out_coordinates) {
        if (x > boundXMin && x < boundXMax && y > boundYMin && y < boundYMax) {
            return false;
        }
    }

    return true;
}

