const BENIGN_PATTERNS = [
  /(^|\.)microsoft\.com$/i,
  /(^|\.)w3\.org$/i,
  /(^|\.)cloudflare\.com$/i,
  /(^|\.)akamai\.net$/i,
  /(^|\.)fastly\.net$/i,
];

const LOW_PATTERNS = [
  /(^|\.)github\.com$/i,
  /(^|\.)github\.io$/i,
  /(^|\.)npmjs\.com$/i,
  /(^|\.)npm\.js$/i,
  /(^|\.)google\.com$/i,
  /(^|\.)aws\.amazon\.com$/i,
];

const HIGH_PATTERNS = [
  /^\d{1,3}(\.\d{1,3}){3}(:\d+)?$/,
  /^\d{1,3}(\.\d{1,3}){3}\//,
  /(^|\.)(xn--[a-z0-9-]+\.)/i,
  /(^|\.)(\d+-\d+-[a-z0-9-]+\.)/i,
  /(^|\.)([a-z0-9-]+-\d{4,}\.)/i,
];

function getHostname(url: string): string | null {
  try {
    const parsed = new URL(url);
    return parsed.hostname.toLowerCase();
  } catch {
    const match = url.match(/^[a-z]+:\/\/([^\/:]+)/i);
    return match ? match[1].toLowerCase() : null;
  }
}

function categorize(url: string): string {
  const hostname = getHostname(url);
  if (!hostname) return 'unknown';

  const isRawIp = /^\d{1,3}(\.\d{1,3}){3}$/.test(hostname) ||
                  /^\[?[0-9a-f:]+\]?$/i.test(hostname);
  if (isRawIp) return 'high';

  if (HIGH_PATTERNS.some(p => p.test(hostname))) return 'high';
  if (BENIGN_PATTERNS.some(p => p.test(hostname))) return 'benign';
  if (LOW_PATTERNS.some(p => p.test(hostname))) return 'low';
  return 'unknown';
}

rl.on('line', (line) => {
  const trimmed = line.trim();
  if (trimmed) {
    console.log(categorize(trimmed));
  }
});
