import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = reader.readLine()) != null) {
            int[] result = parseInput(line.trim());
            System.out.println("[" + result[0] + ", " + result[1] + "]");
        }
    }

    private static int[] parseInput(String input) {
        if (input.isEmpty()) {
            throw new IllegalArgumentException("ValueError");
        }

        String s = input.trim();

        if (s.startsWith("[") || s.startsWith("(")) {
            if (s.length() < 2) {
                throw new IllegalArgumentException("ValueError");
            }
            char open = s.charAt(0);
            char close = s.charAt(s.length() - 1);
            if ((open == '[' && close != ']') || (open == '(' && close != ')')) {
                throw new IllegalArgumentException("ValueError");
            }
            s = s.substring(1, s.length() - 1).trim();
        }

        String[] parts;
        if (s.contains(",")) {
            parts = s.split(",", -1);
        } else {
            parts = s.split("\\s+", -1);
        }

        if (parts.length == 1) {
            int value = parseInteger(parts[0]);
            return new int[]{value, value};
        } else if (parts.length == 2) {
            int first = parseInteger(parts[0]);
            int second = parseInteger(parts[1]);
            return new int[]{first, second};
        } else {
            throw new IllegalArgumentException("ValueError");
        }
    }

    private static int parseInteger(String token) {
        String value = token.trim();
        if (!value.matches("-?\\d+")) {
            throw new IllegalArgumentException("ValueError");
        }
        try {
            return Integer.parseInt(value);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("ValueError");
        }
    }
}
