        int[] shape;
        Node(double[] data, int[] shape) {
            this.data = data;
            this.shape = shape;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String dataLine = sc.nextLine();
        String nLine = sc.nextLine();
        String axisLine = sc.nextLine();
        // xvals is not needed for plain array output
        // sc.nextLine();

        Node node = parseArray(dataLine);
        int[] axes = parseIntListOrScalar(axisLine);
        int[] ns = parseIntListOrScalar(nLine);

        if (ns.length == 1 && axes.length > 1) {
            int v = ns[0];
            ns = new int[axes.length];
            Arrays.fill(ns, v);
        }

        double[] data = node.data;
        int[] shape = node.shape;

        for (int i = 0; i < axes.length; i++) {
            int axis = axes[i];
            int n = ns[i];
            if (n <= 1) continue;
            DownResult r = downsample(data, shape, n, axis);
            data = r.data;
            shape = r.shape;
        }

        System.out.println(formatArray(data, shape));
    }

    static class DownResult {
        double[] data;
        int[] shape;
        DownResult(double[] data, int[] shape) {
            this.data = data;
            this.shape = shape;
        }
    }

    static DownResult downsample(double[] data, int[] shape, int n, int axis) {
        int ndim = shape.length;
        int nPts = shape[axis] / n;
        if (nPts == 0) {
            int[] newShape = shape.clone();
            newShape[axis] = 0;
            return new DownResult(new double[0], newShape);
        }

        int[] newShape = shape.clone();
        newShape[axis] = nPts;

        int totalOut = 1;
        for (int s : newShape) totalOut *= s;

        double[] out = new double[totalOut];

        int axisStride = 1;
        for (int i = axis + 1; i < ndim; i++) {
            axisStride *= shape[i];
        }

        int block = nPts * axisStride;

        for (int o = 0; o < totalOut; o++) {
            int prefix = o / block;
            int rem = o % block;
            int axisIndex = rem / axisStride;
            int after = rem % axisStride;

            int base = prefix * (block * n) + axisIndex * n * axisStride + after;
            double sum = 0.0;
            for (int k = 0; k < n; k++) {
                sum += data[base + k * axisStride];
            }
            out[o] = sum / n;
        }

        return new DownResult(out, newShape);
    }

    static Node parseArray(String s) {
        Parser p = new Parser(s);
        Node node = p.parseValue();
        return node;
    }

    static class Parser {
        String s;
        int pos;

        Parser(String s) {
            this.s = s;
            this.pos = 0;
        }

        Node parseValue() {
            skipWhitespace();
            if (pos < s.length() && s.charAt(pos) == '[') {
                return parseList();
            } else {
                return parseNumber();
            }
        }

        Node parseList() {
            pos++; // consume '['
            List<Node> children = new ArrayList<>();

            skipWhitespace();
            if (pos < s.length() && s.charAt(pos) == ']') {
                pos++;
                return new Node(new double[0], new int[]{0});
            }

            while (true) {
                skipWhitespace();
                Node child = parseValue();
                children.add(child);
                skipWhitespace();

                if (pos < s.length() && s.charAt(pos) == ',') {
                    pos++;
                } else if (pos < s.length() && s.charAt(pos) == ']') {
                    pos++;
                    break;
                } else {
                    throw new RuntimeException("Invalid array format");
                }
            }

            int[] firstShape = children.get(0).shape;
            for (Node child : children) {
                if (!Arrays.equals(firstShape, child.shape)) {
                    throw new RuntimeException("Inconsistent array shape");
                }
            }

            int childLen = children.get(0).data.length;
            int[] shape = new int[firstShape.length + 1];
            shape[0] = children.size();
            System.arraycopy(firstShape, 0, shape, 1, firstShape.length);

            double[] data = new double[children.size() * childLen];
            int offset = 0;
            for (Node child : children) {
                System.arraycopy(child.data, 0, data, offset, child.data.length);
                offset += child.data.length;
            }

            return new Node(data, shape);
        }

        Node parseNumber() {
            skipWhitespace();
            int start = pos;
            while (pos < s.length() && !isDelimiter(s.charAt(pos))) {
                pos++;
            }
            String num = s.substring(start, pos).trim();
            if (num.isEmpty()) {
                throw new RuntimeException("Expected number");
            }
            double v = Double.parseDouble(num);
            return new Node(new double[]{v}, new int[0]);
        }

        boolean isDelimiter(char c) {
            return c == ',' || c == ']' || Character.isWhitespace(c);
        }

        void skipWhitespace() {
            while (pos < s.length() && Character.isWhitespace(s.charAt(pos))) {
                pos++;
            }
        }
    }

    static int[] parseIntListOrScalar(String line) {
        line = line.trim();
        if (line.startsWith("[")) {
            String content = line.substring(1, line.lastIndexOf(']'));
            String[] parts = content.split(",");
            int[] arr = new int[parts.length];
            for (int i = 0; i < parts.length; i++) {
                arr[i] = Integer.parseInt(parts[i].trim());
            }
            return arr;
        } else {
            return new int[]{Integer.parseInt(line)};
        }
    }

    static String formatArray(double[] data, int[] shape) {
        StringBuilder sb = new StringBuilder();
        buildArray(data, shape, 0, 0, sb);
        return sb.toString();
    }

    static int buildArray(double[] data, int[] shape, int dim, int offset, StringBuilder sb) {
        if (dim == shape.length - 1) {
            sb.append('[');
            int count = shape[dim];
            int idx = offset;
            for (int i = 0; i < count; i++) {
                if (i > 0) sb.append(", ");
                sb.append(formatDouble(data[idx++]));
            }
            sb.append(']');
            return idx;
        } else {
            sb.append('[');
            int blockSize = 1;
            for (int i = dim + 1; i < shape.length; i++) {
                blockSize *= shape[i];
            }
            int idx = offset;
            int count = shape[dim];
            for (int i = 0; i < count; i++) {
                if (i > 0) sb.append(", ");
                idx = buildArray(data, shape, dim + 1, idx, sb);
            }
            sb.append(']');
            return idx;
        }
    }

    static String formatDouble(double v) {
        if (Double.isFinite(v) && v == Math.rint(v) && Math.abs(v) < 1e15) {
            return Long.toString((long) v);
        }
        return Double.toString(v);
    }
}
