入力行をPython風タプルとして解析し、タプルなら第1要素をモデル・第2要素をインデックスとして復号し、タプルでなければ既定値を用いて出力します。
```java
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.trim().isEmpty()) continue;
            System.out.println(decodeLensPackage(line));
        }
    }

    private static String decodeLensPackage(String input) {
        Object parsed = parseExpr(input.trim());
        if (parsed instanceof List) {
            List<?> pkg = (List<?>) parsed;
            Object model = pkg.get(0);
            List<?> indices = (List<?>) pkg.get(1);
            int bgn = Integer.parseInt(indices.get(0).toString());
            int end = Integer.parseInt(indices.get(1).toString());
            return "[" + formatValue(model) + ", " + bgn + ", " + end + "]";
        } else {
            return "[" + formatValue(parsed) + ", 1, -1]";
        }
    }

    private static Object parseExpr(String s) {
        s = s.trim();
        if (s.startsWith("(") && s.endsWith(")")) {
            String inner = s.substring(1, s.length() - 1).trim();
            if (inner.isEmpty() || inner.endsWith(",") || hasTopLevelComma(inner)) {
                List<Object> list = new ArrayList<>();
                if (!inner.isEmpty()) {
                    for (String part : splitTopLevel(inner)) {
                        String p = part.trim();
                        if (!p.isEmpty()) {
                            list.add(parseExpr(p));
                        }
                    }
                }
                return list;
            } else {
                return parseExpr(inner);
            }
        }
        return s;
    }

    private static boolean hasTopLevelComma(String s) {
        int depth = 0;
        char quote = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (quote != 0) {
                if (c == quote) quote = 0;
                continue;
            }
            if (c == '\'' || c == '"') {
                quote = c;
            } else if (c == '(' || c == '[' || c == '{') {
                depth++;
            } else if (c == ')' || c == ']' || c == '}') {
                depth--;
            } else if (c == ',' && depth == 0) {
                return true;
            }
        }
        return false;
    }

    private static List<String> splitTopLevel(String s) {
        List<String> parts = new ArrayList<>();
        int depth = 0;
        char quote = 0;
        StringBuilder current = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (quote != 0) {
                if (c == quote) quote = 0;
                current.append(c);
                continue;
            }
            if (c == '\'' || c == '"') {
                quote = c;
                current.append(c);
            } else if (c == '(' || c == '[' || c == '{') {
                depth++;
                current.append(c);
            } else if (c == ')' || c == ']' || c == '}') {
                depth--;
                current.append(c);
            } else if (c == ',' && depth == 0) {
                parts.add(current.toString());
                current.setLength(0);
            } else {
                current.append(c);
            }
        }
        if (current.length() > 0) {
            parts.add(current.toString());
        }
        return parts;
    }

    private static String formatValue(Object value) {
        if (value instanceof List) {
            List<?> list = (List<?>) value;
            StringBuilder sb = new StringBuilder("(");
            for (int i = 0; i < list.size(); i++) {
                if (i > 0) sb.append(", ");
                sb.append(formatValue(list.get(i)));
            }
            sb.append(")");
            return sb.toString();
        }
        return value.toString();
    }
}
