    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in, StandardCharsets.UTF_8));
        String firstLine = reader.readLine();
        if (firstLine == null) {
            return;
        }

        int n;
        try {
            n = Integer.parseInt(firstLine.trim());
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("n must be an integer", e);
        }
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        List<String> tokens = new ArrayList<>();
        String line;
        while ((line = reader.readLine()) != null) {
            for (String token : line.trim().split("\\s+")) {
                if (!token.isEmpty()) {
                    tokens.add(token);
                }
            }
        }

        if (tokens.size() != 1 && tokens.size() != n) {
            throw new IllegalArgumentException("value must be one integer or " + n + " integers");
        }

        int[] values = new int[n];
        if (tokens.size() == 1) {
            int v = parsePositiveInt(tokens.get(0));
            for (int i = 0; i < n; i++) {
                values[i] = v;
            }
        } else {
            for (int i = 0; i < n; i++) {
                values[i] = parsePositiveInt(tokens.get(i));
            }
        }

        StringJoiner joiner = new StringJoiner(", ", "[", "]");
        for (int v : values) {
            joiner.add(Integer.toString(v));
        }
        System.out.println(joiner.toString());
    }

    private static int parsePositiveInt(String s) {
        int v;
        try {
            v = Integer.parseInt(s.trim());
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("value must be an integer", e);
        }
        if (v <= 0) {
            throw new IllegalArgumentException("value must be positive");
        }
        return v;
    }
}
