#include <iostream>
#include <string>
#include <vector>
#include <cctype>

struct Node {
    bool isContainer = false;
    char type = 0; // 'L' = list, 'T' = tuple, 0 = scalar
    std::string value;
    std::vector<Node> children;
};

void skipSpaces(const std::string& s, size_t& i) {
    while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) {
        ++i;
    }
}

Node parseValue(const std::string& s, size_t& i);

Node parseContainer(const std::string& s, size_t& i, char open) {
    char close = (open == '[') ? ']' : ')';
    Node node;
    node.isContainer = true;
    node.type = (open == '[') ? 'L' : 'T';
    ++i; // skip opening bracket

    skipSpaces(s, i);
    if (i < s.size() && s[i] == close) {
        ++i;
        return node;
    }

    while (true) {
        skipSpaces(s, i);
        node.children.push_back(parseValue(s, i));

        skipSpaces(s, i);
        if (i < s.size() && s[i] == ',') {
            ++i;
            skipSpaces(s, i);
            if (i < s.size() && s[i] == close) {
                // trailing comma, e.g. (1,)
                ++i;
                break;
            }
        } else if (i < s.size() && s[i] == close) {
            ++i;
            break;
        } else {
            break;
        }
    }

    return node;
}

Node parseValue(const std::string& s, size_t& i) {
    skipSpaces(s, i);

    if (i < s.size() && (s[i] == '[' || s[i] == '(')) {
        return parseContainer(s, i, s[i]);
    }

    Node node;
    node.isContainer = false;
    node.type = 0;

    while (i < s.size() && s[i] != ',' && s[i] != ']' && s[i] != ')' &&
           !std::isspace(static_cast<unsigned char>(s[i]))) {
        node.value.push_back(s[i]);
        ++i;
    }

    return node;
}

void collectScalars(const Node& node, std::vector<std::string>& out) {
    if (!node.isContainer) {
        out.push_back(node.value);
        return;
    }

    for (const auto& child : node.children) {
        collectScalars(child, out);
    }
}

std::string unflattenToString(const Node& tmpl, const std::vector<std::string>& obj, size_t& idx) {
    if (!tmpl.isContainer) {
        return obj[idx++];
    }

    std::string result;

    if (tmpl.type == 'L') {
        result += "[";
    } else {
        result += "(";
    }

    for (size_t i = 0; i < tmpl.children.size(); ++i) {
        if (i > 0) {
            result += ", ";
        }
        result += unflattenToString(tmpl.children[i], obj, idx);
    }

    if (tmpl.type == 'L') {
        result += "]";
    } else {
        if (tmpl.children.size() == 1) {
            result += ",";
        }
        result += ")";
    }

    return result;
}

int main() {
    std::string objLine;
    std::string tmplLine;

    if (!std::getline(std::cin, objLine)) {
        return 0;
    }
    if (!std::getline(std::cin, tmplLine)) {
        return 0;
    }

    size_t objPos = 0;
    Node objNode = parseValue(objLine, objPos);

    size_t tmplPos = 0;
    Node tmplNode = parseValue(tmplLine, tmplPos);

    std::vector<std::string> objValues;
    collectScalars(objNode, objValues);

    size_t idx = 0;
    std::cout << unflattenToString(tmplNode, objValues, idx) << std::endl;

    return 0;
}
