using namespace std;

// 空白を除去する
string trim(const string& s) {
    string r;
    for (char c : s) {
        if (!isspace(static_cast<unsigned char>(c))) r += c;
    }
    return r;
}

// 数値または入れ子になったリストを表すノード
struct Node {
    int value = 0;
    vector<Node> children;
    bool isList = false;
};

// Python形式のリテラルをパースする
Node parseValue(const string& s, size_t& pos) {
    if (s[pos] == '[') {
        Node node;
        node.isList = true;
        ++pos;
        while (true) {
            while (pos < s.size() && (s[pos] == ',' || isspace(static_cast<unsigned char>(s[pos])))) ++pos;
            if (pos < s.size() && s[pos] == ']') {
                ++pos;
                break;
            }
            node.children.push_back(parseValue(s, pos));
        }
        return node;
    } else {
        size_t start = pos;
        while (pos < s.size() && (isdigit(static_cast<unsigned char>(s[pos])) || s[pos] == '-')) ++pos;
        Node node;
        node.value = stoi(s.substr(start, pos - start));
        return node;
    }
}

Node parse(const string& s) {
    size_t pos = 0;
    return parseValue(s, pos);
}

// ノードを転置する
Node transposeNode(const Node& node, const vector<int>& axes) {
    if (!node.isList) return node;

    // 次元を求める
    vector<int> dims;
    const Node* cur = &node;
    while (cur->isList) {
        dims.push_back(static_cast<int>(cur->children.size()));
        cur = &cur->children[0];
    }

    int ndim = static_cast<int>(dims.size());

    // 軸指定がない場合は逆順にする
    vector<int> actualAxes = axes;
    if (actualAxes.empty()) {
        actualAxes.resize(ndim);
        for (int i = 0; i < ndim; ++i) actualAxes[i] = ndim - 1 - i;
    }

    // 多次元の添え字を列挙する
    vector<int> indices(ndim, 0);
    auto indexToNode = [&](const vector<int>& idx) -> const Node* {
        const Node* p = &node;
        for (int i = 0; i < ndim; ++i) {
            p = &p->children[idx[i]];
        }
        return p;
    };

    auto makeIndex = [&](const vector<int>& transIdx) {
        vector<int> idx(ndim);
        for (int i = 0; i < ndim; ++i) idx[i] = transIdx[actualAxes[i]];
        return idx;
    };

    // 転置後の構造を作る
    Node result;
    result.isList = true;
    vector<int> newDims(ndim);
    for (int i = 0; i < ndim; ++i) newDims[i] = dims[actualAxes[i]];

    // 各次元のイテレータ用
    function<void(int, Node*)> build = [&](int depth, Node* parent) {
        if (depth == ndim) {
            parent->isList = true;
            return;
        }
        parent->isList = true;
        for (int i = 0; i < newDims[depth]; ++i) {
            Node child;
            parent->children.push_back(child);
        }
    };

    // 空の転置先構造を作る
    result.isList = true;
    function<void(int, Node*)> makeShape = [&](int depth, Node* parent) {
        parent->isList = true;
        if (depth == ndim) return;
        int size = newDims[depth];
        parent->children.resize(size);
        for (int i = 0; i < size; ++i) {
            makeShape(depth + 1, &parent->children[i]);
        }
    };
    if (ndim > 0) {
        makeShape(0, &result);
    }

    // 要素を埋める
    function<void(int, Node*, const vector<int>&)> fill = [&](int depth, Node* parent, const vector<int>& transIdx) {
        if (depth == ndim) {
            vector<int> idx = makeIndex(transIdx);
            const Node* src = indexToNode(idx);
            *parent = *src;
            return;
        }
        for (int i = 0; i < newDims[depth]; ++i) {
            vector<int> next = transIdx;
            next.push_back(i);
            fill(depth + 1, &parent->children[i], next);
        }
    };

    if (ndim > 0) {
        fill(0, &result, {});
    } else {
        result = node;
    }

    return result;
}

// ノードを出力する
void printNode(const Node& node) {
    if (!node.isList) {
        cout << node.value;
        return;
    }
    cout << "[";
    for (size_t i = 0; i < node.children.size(); ++i) {
        if (i) cout << ", ";
        printNode(node.children[i]);
    }
    cout << "]";
}

int main() {
    string line1, line2;
    if (!getline(cin, line1)) return 0;
    if (!getline(cin, line2)) return 0;

    Node volumes = parse(trim(line1));
    string dirRaw = trim(line2);
    string dir = dirRaw;
    if (!dir.empty() && dir.front() == '\'') dir = dir.substr(1);
    if (!dir.empty() && dir.back() == '\'') dir.pop_back();

    vector<int> axes;
    if (dir == "axial" || dir == "2") {
        // 軸を z(2) から先頭へ: (2,0,1)
        axes = {2, 0, 1};
    } else if (dir == "sagittal" || dir == "0") {
        // 軸を x(0) から先頭へ: (0,1,2)
        axes = {0, 1, 2};
    } else if (dir == "coronal" || dir == "1") {
        // 軸を y(1) から先頭へ: (1,0,2)
        axes = {1, 0, 2};
    }

    // volumes は「ボリュームのリスト」なので、各ボリュームごとに転置する
    Node result;
    result.isList = true;
    if (volumes.isList) {
        for (const auto& vol : volumes.children) {
            result.children.push_back(transposeNode(vol, axes));
        }
    } else {
        result.children.push_back(transposeNode(volumes, axes));
    }

    printNode(result);
    cout << endl;

    return 0;
}
