using System;
using System.Collections.Generic;
using System.Linq;

class ValueError : Exception
{
    public ValueError(string message) : base(message) { }
}

class Program
{
    static void Main()
    {
        var values = new List<int>();
        string line;
        while ((line = Console.ReadLine()) != null)
        {
            foreach (var part in line.Split((char[])null, StringSplitOptions.RemoveEmptyEntries))
            {
                if (!int.TryParse(part, out int v))
                    throw new ValueError("Invalid integer: " + part);
                values.Add(v);
            }
        }

        if (values.Count < 2)
            throw new ValueError("At least output_indices and chunk_size are required.");

        int chunkSize = values[values.Count - 1];
        if (chunkSize <= 0)
            throw new ValueError("chunk_size must be positive.");

        int[] outputIndices = values.Take(values.Count - 1).ToArray();
        if (outputIndices.Any(x => x < 0))
            throw new ValueError("output_indices must be non-negative.");

        int[] sendDestChips = new int[outputIndices.Length];
        int[] sendLocalRows = new int[outputIndices.Length];

        for (int i = 0; i < outputIndices.Length; i++)
        {
            sendDestChips[i] = outputIndices[i] / chunkSize;
            sendLocalRows[i] = outputIndices[i] % chunkSize;
        }

        var result = sendDestChips.Concat(sendLocalRows).ToArray();
        Console.WriteLine("[" + string.Join(", ", result) + "]");
    }
}
