using System;
using System.Collections.Generic;
using System.Text;
using System.Text.Json;

class Program
{
    static void Main()
    {
        string line;
        while ((line = Console.ReadLine()) != null)
        {
            Console.WriteLine(ExtractContent(line));
        }
    }

    static string ExtractContent(string content)
    {
        if (string.IsNullOrEmpty(content)) return string.Empty;

        string trimmed = content.Trim();
        if (trimmed.Length == 0) return string.Empty;

        if (trimmed[0] == '{' || trimmed[0] == '[' || trimmed[0] == '"')
        {
            try
            {
                using (JsonDocument doc = JsonDocument.Parse(trimmed))
                {
                    return ExtractContent(doc.RootElement);
                }
            }
            catch (JsonException)
            {
                return trimmed;
            }
        }

        return trimmed;
    }

    static string ExtractContent(JsonElement element)
    {
        switch (element.ValueKind)
        {
            case JsonValueKind.String:
                return element.GetString()?.Trim() ?? string.Empty;

            case JsonValueKind.Array:
                var sb = new StringBuilder();
                foreach (var item in element.EnumerateArray())
                {
                    string part = ExtractBlock(item);
                    if (!string.IsNullOrEmpty(part))
                    {
                        if (sb.Length > 0) sb.Append('\n');
                        sb.Append(part);
                    }
                }
                return sb.ToString().Trim();

            case JsonValueKind.Object:
                if (element.TryGetProperty("text", out var textProp) && textProp.ValueKind == JsonValueKind.String)
                {
                    return textProp.GetString()?.Trim() ?? string.Empty;
                }
                return string.Empty;

            default:
                return string.Empty;
        }
    }

    static string ExtractBlock(JsonElement item)
    {
        if (item.ValueKind == JsonValueKind.String)
        {
            return item.GetString() ?? string.Empty;
        }

        if (item.ValueKind != JsonValueKind.Object)
        {
            return string.Empty;
        }

        if (!item.TryGetProperty("type", out var typeProp) || typeProp.ValueKind != JsonValueKind.String)
        {
            return string.Empty;
        }

        string type = typeProp.GetString();
        switch (type)
        {
            case "text":
                if (item.TryGetProperty("text", out var textProp) && textProp.ValueKind == JsonValueKind.String)
                {
                    return textProp.GetString() ?? string.Empty;
                }
                return string.Empty;

            case "tool_use":
                return FormatToolUse(item);

            case "tool_result":
                string toolName = "Unknown";
                if (item.TryGetProperty("tool_use_id", out var idProp) && idProp.ValueKind == JsonValueKind.String)
                {
                    string id = idProp.GetString();
                    // 標準入力からはツール名マップを渡せないため、この実装では "Unknown" になる。
                    // 必要なら JSON の別フィールドから読み取れるように拡張できる。
                }

                if (item.TryGetProperty("content", out var contentProp))
                {
                    return FormatToolResult(contentProp, toolName);
                }
                return string.Empty;

            default:
                return string.Empty;
        }
    }

    static string FormatToolUse(JsonElement item)
    {
        string name = "Unknown";
        string id = string.Empty;
        string input = string.Empty;

        if (item.TryGetProperty("name", out var nameProp) && nameProp.ValueKind == JsonValueKind.String)
        {
            name = nameProp.GetString();
        }

        if (item.TryGetProperty("id", out var idProp) && idProp.ValueKind == JsonValueKind.String)
        {
            id = idProp.GetString();
        }

        if (item.TryGetProperty("input", out var inputProp))
        {
            input = inputProp.GetRawText();
        }

        return $"<tool_use id=\"{id}\" name=\"{name}\">\n{input}\n</tool_use>";
    }

    static string FormatToolResult(JsonElement content, string toolName)
    {
        string text = ExtractContent(content);

        if (string.IsNullOrEmpty(text))
        {
            return string.Empty;
        }

        return $"<{toolName}_result>\n{text}\n</{toolName}_result>";
    }
}
