// parseDecomposition は phi_m の素因数分解表現を (素数, 指数) のスライスに変換する。
func parseDecomposition(s string) [][2]int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil
	}

	// 例: "[(2, 1), (5, 1)]" や "[[2,1],[5,1]]" から数値列を取り出す
	fields := strings.FieldsFunc(s, func(r rune) bool {
		return !(r >= '0' && r <= '9' || r == '-')
	})

	var nums []int64
	for _, f := range fields {
		if f == "-" {
			continue
		}
		n, err := strconv.ParseInt(f, 10, 64)
		if err == nil {
			nums = append(nums, n)
		}
	}

	var result [][2]int64
	for i := 0; i+1 < len(nums); i += 2 {
		result = append(result, [2]int64{nums[i], nums[i+1]})
	}
	return result
}

// powMod は a^e mod m を計算する。
func powMod(a, e, m int64) int64 {
	if m == 1 {
		return 0
	}
	a %= m
	if a < 0 {
		a += m
	}
	result := int64(1)
	for e > 0 {
		if e&1 == 1 {
			result = result * a % m
		}
		a = a * a % m
		e >>= 1
	}
	return result
}

// gcd は最大公約数を返す。
func gcd(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)

	readInt := func() (int64, bool) {
		if !scanner.Scan() {
			return 0, false
		}
		n, err := strconv.ParseInt(strings.TrimSpace(scanner.Text()), 10, 64)
		if err != nil {
			return 0, false
		}
		return n, true
	}

	element, ok := readInt()
	if !ok {
		return
	}
	modulus, ok := readInt()
	if !ok {
		return
	}
	phiM, ok := readInt()
	if !ok {
		return
	}
	if !scanner.Scan() {
		return
	}
	decompLine := scanner.Text()

	decomp := parseDecomposition(decompLine)

	// 法が1の場合は位数は1
	if modulus == 1 {
		fmt.Println(1)
		return
	}

	element %= modulus
	if element < 0 {
		element += modulus
	}

	// 元が法と互いに素でない場合は位数は定義されないが、ここでは0を出力する
	if gcd(element, modulus) != 1 {
		fmt.Println(0)
		return
	}

	order := phiM
	for _, pe := range decomp {
		p := pe[0]
		for order%p == 0 && powMod(element, order/p, modulus) == 1 {
			order /= p
		}
	}

	fmt.Println(order)
}
