		parts := strings.Split(input, ":")
		if len(parts) != 3 {
			return
		}
		deg, err1 := strconv.ParseFloat(parts[0], 64)
		min, err2 := strconv.ParseFloat(parts[1], 64)
		sec, err3 := strconv.ParseFloat(parts[2], 64)
		if err1 != nil || err2 != nil || err3 != nil {
			return
		}
		dec := deg + min/60.0 + sec/3600.0
		if back != 0 {
			fmt.Printf("%.10f\n", dec)
		} else {
			fmt.Printf("%.10f\n", dec)
		}
	} else {
		// decimal degrees → deg:min:sec
		dec, err := strconv.ParseFloat(input, 64)
		if err != nil {
			return
		}
		if back == 0 {
			// 10進度を60進度（deg:min:sec）へ変換
			deg := int(dec)
			minFloat := (dec - float64(deg)) * 60
			min := int(minFloat)
			sec := (minFloat - float64(min)) * 60
			fmt.Printf("%d:%d:%.10f\n", deg, min, sec)
		} else {
