func intToBits(n, width int) []int {
	bits := []int{}
	for n > 0 {
		bits = append(bits, n&1)
		n >>= 1
	}
	for len(bits) < width {
		bits = append(bits, 0)
	}
	if len(bits) == 0 {
		bits = append(bits, 0)
	}
	return bits
}

