use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        let text = line.trim();
        if text.is_empty() {
            continue;
        }

        // URLデコード（元の実装と同じ順序・対象）
        let decoded = text
            .replace("%09", "\t")
            .replace("%0A", "\n")
            .replace("%0D", "\r")
            .replace("%25", "%")
            .replace("%3D", "=")
            .replace("%26", "&")
            .replace("%2C", ",")
            .replace("%28", "(")
            .replace("%29", ")");

        // 区切り文字の決定: 最初の '=' または ' ' を探す
        let sep = decoded.chars().find(|&c| c == '=' || c == ' ');
        if sep.is_none() {
            // 元のコードはエラー終了するが、ここでは不正行として何も出さない
            continue;
        }

        // 属性ペアを効率的に走査
        let bytes = decoded.as_bytes();
        let mut i = 0;
        let n = bytes.len();
        let mut attributes: Vec<(String, String)> = Vec::new();

        while i < n {
            // キー読み取り: 空白または '=' まで
            let key_start = i;
            while i < n && bytes[i] != b'=' && bytes[i] != b' ' {
                i += 1;
            }
            if i >= n {
                break;
            }
            let key = &decoded[key_start..i];

            // 区切り文字を読み飛ばし
            while i < n && (bytes[i] == b'=' || bytes[i] == b' ') {
                i += 1;
            }

            // 値読み取り
            let value_start = i;
            let mut value_end = n;

            // 引用符で始まる場合
            if i < n && bytes[i] == b'"' {
                let quote_start = i;
                i += 1;
                while i < n && bytes[i] != b'"' {
                    i += 1;
                }
                if i < n {
                    i += 1; // 閉じ引用符を越える
                }
                value_end = if i <= n && i > quote_start + 1 {
                    i - 1
                } else {
                    i
                };
                // セミコロンまで読み飛ばし
                while i < n && bytes[i] != b';' {
                    i += 1;
                }
            } else {
                // 引用符なし: セミコロンまで
                while i < n && bytes[i] != b';' {
                    i += 1;
                }
                value_end = i;
            }

            let raw_value = &decoded[value_start..value_end];
            let value = if raw_value.starts_with('"') && raw_value.ends_with('"') {
                &raw_value[1..raw_value.len() - 1]
            } else {
                raw_value
            };

            attributes.push((key.to_string(), value.to_string()));

            // セミコロンを読み飛ばす
            while i < n && bytes[i] == b';' {
                i += 1;
            }
            // 空白のみの区切りを読み飛ばす
            while i < n && (bytes[i] == b' ' || bytes[i] == b'\t') {
                i += 1;
            }
        }

        // 辞書風の出力
        let mut first = true;
        print!("{{");
        for (k, v) in &attributes {
            if !first {
                print!(", ");
            }
            first = false;
            print!("{:?}: {:?}", k, v);
        }
        println!("}}");
    }
}
