## 実装方針

標準入力から「レコード（勾配ベクトル）」と「クリッピングノルム（params 内の `param1`）」を読み取り、その勾配の L2 ノルムがクリッピングノルムを超える場合にのみ、超えた分だけ全体をスケールしてクリップし、結果のベクトルを1行で出力します。

```rust
use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    // 1行目: record 例: [1, 2, 3]
    let record_line = match lines.next() {
        Some(Ok(line)) => line,
        _ => return,
    };

    // 2行目: params 例: {"param1": 1}
    let params_line = match lines.next() {
        Some(Ok(line)) => line,
        _ => return,
    };

    // 3行目: 念のため読み飛ばす（無くても動作する）
    if let Some(Ok(_)) = lines.next() {}

    // record の数値列をパース
    let mut record: Vec<f64> = Vec::new();
    let trimmed = record_line.trim();
    let inner = trimmed.trim_start_matches('[').trim_end_matches(']');
    for part in inner.split(',') {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }
        match part.parse::<f64>() {
            Ok(v) => record.push(v),
            Err(_) => return,
        }
    }

    // params から param1 の値をパース
    let params_trimmed = params_line.trim();
    let mut clip_norm: f64 = 1.0;
    if let Some(pos) = params_trimmed.find("param1") {
        let after = &params_trimmed[pos + "param1".len()..];
        if let Some(colon) = after.find(':') {
            let value_part = &after[colon + 1..];
            let value_part: String = value_part
                .chars()
                .take_while(|c| c.is_ascii_digit() || *c == '.' || *c == '-' || *c == '+' || *c == 'e' || *c == 'E')
                .collect();
            if let Ok(v) = value_part.trim().parse::<f64>() {
                clip_norm = v;
            }
        }
    }

    // L2 ノルムを計算
    let norm: f64 = record.iter().map(|v| v * v).sum::<f64>().sqrt();

    // クリッピング処理
    if norm > clip_norm && clip_norm >= 0.0 {
        let scale = clip_norm / norm;
        for v in record.iter_mut() {
            *v *= scale;
        }
    }

    // 結果を [x, y, z] 形式で出力
    let result: Vec<String> = record.iter().map(|v| v.to_string()).collect();
    println!("[{}]", result.join(", "));
}
